b_spouse_income = observation(entity='Charlie', entity_source='s20', predicate='has no gross income', predicate_source='s4')
b_dependent_of_another = observation(entity='Bob', entity_source='s20', predicate='dependent of another taxpayer', predicate_source='s4')
b_taxpayer_spouse = observation(entity='Alice', entity_source='s20', predicate='spouse of the taxpayer', predicate_source='s4')
b_joint_return = observation(entity='Alice', entity_source='s20', predicate='joint return is not made', predicate_source='s4')
b_tax_year_start = observation(entity='Alice', entity_source='s20', predicate='taxable year of the taxpayer begins', predicate_source='s4')
b_exemption_amount = residual(source='s10', quote='the term \"exemption amount\" means $2,000')
b_phaseout_income = residual(source='s15', quote='adjusted gross income for the taxable year exceeds the applicable amount in effect under section 68(b)')
b_phaseout_percentage = residual(source='s17', quote='2 percentage points for each $2,500 (or fraction thereof)')
b_phaseout_limit = residual(source='s17', quote='the applicable percentage shall not exceed 100 percent')
b_special_rule = residual(source='s19', quote='the term \"exemption amount\" means zero')
@scope('s0') 
def section_151_scope(): 
    return True 
@scope('s1') 
def allowance_of_deductions_scope(): 
    return section_151_scope 
@scope('s2') 
def individual_exemption_scope(): 
    return allowance_of_deductions_scope 
@scope('s3') 
def taxpayer_and_spouse_scope(): 
    return section_151_scope 
@scope('s4') 
def spouse_exemption_scope(): 
    return (taxpayer_and_spouse_scope and b_spouse_income and b_dependent_of_another and b_taxpayer_spouse and b_joint_return and b_tax_year_start) 
@scope('s5') 
def dependent_exemption_scope(): 
    return section_151_scope 
@scope('s6') 
def dependent_exemption_allowance_scope(): 
    return (dependent_exemption_scope and b_dependent_of_another) 
@scope('s7') 
def exemption_amount_scope(): 
    return section_151_scope 
@scope('s8') 
def exemption_amount_definition_scope(): 
    return exemption_amount_scope 
@scope('s9') 
def general_exemption_amount_scope(): 
    return exemption_amount_definition_scope 
@scope('s10') 
def general_exemption_amount_rule_scope(): 
    return (exemption_amount_definition_scope and b_exemption_amount) 
@scope('s11') 
def dependent_exemption_disallowed_scope(): 
    return exemption_amount_definition_scope 
@scope('s12') 
def dependent_exemption_disallowed_rule_scope(): 
    return (dependent_exemption_disallowed_scope and b_dependent_of_another) 
@scope('s13') 
def phaseout_scope(): 
    return exemption_amount_definition_scope 
@scope('s14') 
def phaseout_general_scope(): 
    return phaseout_scope 
@scope('s15') 
def phaseout_income_rule_scope(): 
    return (phaseout_general_scope and b_phaseout_income) 
@scope('s16') 
def phaseout_percentage_rule_scope(): 
    return (phaseout_general_scope and b_phaseout_percentage) 
@scope('s17') 
def phaseout_limit_rule_scope(): 
    return (phaseout_general_scope and b_phaseout_limit) 
@scope('s18') 
def special_rule_scope(): 
    return exemption_amount_definition_scope 
@scope('s19') 
def special_rule_rule_scope(): 
    return (special_rule_scope and b_special_rule) 
@rule('s4', otherwise=False) 
def spouse_exemption_rule(): 
    return (spouse_exemption_scope and b_exemption_amount) 
@rule('s6', otherwise=False) 
def dependent_exemption_rule(): 
    return (dependent_exemption_allowance_scope and b_exemption_amount) 
@rule('s10', otherwise=False) 
def general_exemption_amount_rule(): 
    return (general_exemption_amount_rule_scope and b_exemption_amount) 
@rule('s19', otherwise=False) 
def special_rule_rule(): 
    return (special_rule_rule_scope and b_exemption_amount) 
query = ('Entailment' if (spouse_exemption_rule or dependent_exemption_rule) else 'Contradiction')
